function imageSettings({ spreadsheet, tab, folder, origin }) {
  if (
    !/^[A-Za-z0-9_-]{8,}$/.test(spreadsheet) ||
    !tab.trim() ||
    !/^[A-Za-z0-9_-]{8,}$/.test(folder) ||
    [spreadsheet, folder].some((id) => id.startsWith("YOUR_"))
  ) {
    throw Error("Configure the spreadsheet ID, sheet tab, and Drive folder ID.");
  }
  if (
    !/^https:\/\/(?:[a-z0-9-]+\.)+[a-z]{2,63}$/.test(origin) ||
    /\.(?:invalid|local|localhost)$/.test(origin)
  ) {
    throw Error("Set the exact HTTPS origin for your signed ApyHub download links.");
  }
  const prefix = "'" + tab.replaceAll("'", "''") + "'!";
  return { spreadsheet, folder, origin, prefix, range: prefix + "A1:C" };
}
const settings = {
  spreadsheet: "YOUR_SPREADSHEET_ID",
  tab: "Images",
  folder: "YOUR_DRIVE_FOLDER_ID",
  origin: "https://downloads.example.invalid",
};
return [{ json: imageSettings(settings) }];

function firstImage(values, config) {
  if (!Array.isArray(values) || ["FROM", "TO", "DONE"].some((cell, i) => values[0]?.[i] !== cell)) {
    throw Error("Expected FROM, TO, and DONE in columns A, B, and C.");
  }
  const index = values.findIndex(
    (row, i) => i > 0 && (row[2] === undefined || row[2] === null || row[2] === ""),
  );
  if (index < 0) return null;
  const raw = values[index][0];
  if (typeof raw !== "string" || !raw.trim()) return null;
  const image = raw.trim();
  const path = /^https:\/\/(?:[a-z0-9-]+\.)+[a-z]{2,63}(\/[^\s?#]+)(?:[?#][^\s]*)?$/i.exec(image);
  if (!path) return null;
  let tail;
  try {
    tail = decodeURIComponent(path[1].split("/").at(-1));
  } catch {
    return null;
  }
  const match = /^([^/\\\u0000-\u001f]{1,180})\.(jpg|jpeg|png)$/i.exec(tail);
  if (!match) return null;
  const format = match[2].toLowerCase() === "png" ? "png" : "jpeg";
  const row = index + 1;
  const filename = match[1] + ".webp";
  const endpoint =
    "https://api.eu.apyhub.com/apyhub/convert-" +
    format +
    "-to-webp/url/link?output=" +
    encodeURIComponent(filename);
  return { source: image, filename, row, range: config.prefix + "B" + row + ":C" + row, endpoint };
}

const config = $("Set the sheet, folder, and download origin").first().json;
if ($input.first().json.statusCode !== 200) throw Error("Sheets did not return the image queue.");
const job = firstImage($input.first().json.body.values, config);
return job ? [{ json: { job, request: { url: job.source } } }] : [];

function resultLink(result, config) {
  if (typeof result?.data !== "string") throw Error("ApyHub did not return a signed WebP URL.");
  if (!result.data.startsWith(config.origin + "/") || /[\s#\\]/.test(result.data))
    throw Error("ApyHub returned an unapproved download origin.");
  return result.data;
}
return [
  {
    json: {
      url: resultLink(
        $input.first().json.body,
        $("Set the sheet, folder, and download origin").first().json,
      ),
    },
  },
];

function checkWebP(bytes, mime, status) {
  const contentType = String(mime).split(";")[0].trim().toLowerCase();
  const stringAt = (offset) => String.fromCharCode(...bytes.subarray(offset, offset + 4));
  const riffLength = bytes[4] + bytes[5] * 256 + bytes[6] * 65536 + bytes[7] * 16777216;
  if (
    status !== 200 ||
    !["image/webp", "application/octet-stream"].includes(contentType) ||
    bytes.length < 20 ||
    bytes.length > 2 * 1024 * 1024 ||
    stringAt(0) !== "RIFF" ||
    stringAt(8) !== "WEBP" ||
    !["VP8 ", "VP8L", "VP8X"].includes(stringAt(12)) ||
    riffLength + 8 !== bytes.length
  ) {
    throw Error("The download is not a complete WebP of up to 2 MiB.");
  }
}

const item = $input.first();
const job = $("Select the first pending image").first().json.job;
const data = item.binary?.data;
if (!data) throw Error("ApyHub did not send a WebP file.");
checkWebP(await helpers.getBinaryDataBuffer(0, "data"), data.mimeType, item.json.statusCode);
return [
  {
    json: {
      filename: job.filename,
      folder: $("Set the sheet, folder, and download origin").first().json.folder,
    },
    binary: { data: { ...data, mimeType: "image/webp", fileName: job.filename } },
  },
];

function updateRow(file, job, link) {
  if (typeof file.id !== "string" || !file.id || file.name !== job.filename)
    throw Error("Drive did not confirm the selected WebP upload.");
  return { range: job.range, values: [[link, "x"]], fileId: file.id, row: job.row };
}

const update = updateRow(
  $input.first().json,
  $("Select the first pending image").first().json.job,
  $("Check the signed WebP link").first().json.url,
);
return [
  {
    json: {
      ...update,
      spreadsheet: $("Set the sheet, folder, and download origin").first().json.spreadsheet,
      request: { majorDimension: "ROWS", values: update.values },
    },
  },
];

function verifyUpdate(receipt, update, spreadsheet) {
  const range = String(receipt?.updatedRange ?? "");
  const bang = range.lastIndexOf("!");
  const requestedBang = update.range.lastIndexOf("!");
  const tab = (name) => (name[0] === "'" ? name.slice(1, -1).replaceAll("''", "'") : name);
  if (
    receipt?.spreadsheetId !== spreadsheet ||
    receipt?.updatedCells !== 2 ||
    bang < 0 ||
    tab(range.slice(0, bang)) !== tab(update.range.slice(0, requestedBang)) ||
    range.slice(bang) !== update.range.slice(requestedBang)
  ) {
    throw Error(
      "Sheets did not confirm the two cells on the selected row. Check Drive and Sheets before retrying.",
    );
  }
  return { row: update.row, driveFileId: update.fileId };
}

const update = $("Prepare the linked row update").first().json;
return [{ json: verifyUpdate($input.first().json.body, update, update.spreadsheet) }];
